insert into public.word_examples (word_id, order_index, sentence_en, sentence_vi) values
('00000701-0000-4000-8000-000000000701', 1, 'Football is my favorite sport.', 'Bóng đá là môn thể thao yêu thích của tôi.'),
('00000701-0000-4000-8000-000000000701', 2, 'She plays a lot of sport at school.', 'Cô ấy chơi rất nhiều môn thể thao ở trường.'),
('00000701-0000-4000-8000-000000000701', 3, 'Sport keeps your body and mind healthy.', 'Thể thao giữ cho cơ thể và tinh thần bạn khoẻ mạnh.'),
('00000702-0000-4000-8000-000000000702', 1, 'He plays football every Sunday.', 'Anh ấy chơi bóng đá vào mỗi Chủ nhật.'),
('00000702-0000-4000-8000-000000000702', 2, 'Vietnam won the football match last night.', 'Việt Nam đã thắng trận bóng đá tối qua.'),
('00000702-0000-4000-8000-000000000702', 3, 'My son wants a new football.', 'Con trai tôi muốn một quả bóng đá mới.'),
('00000703-0000-4000-8000-000000000703', 1, 'Tall players have an advantage in basketball.', 'Cầu thủ cao có lợi thế trong bóng rổ.'),
('00000703-0000-4000-8000-000000000703', 2, 'We play basketball after class.', 'Chúng tôi chơi bóng rổ sau giờ học.'),
('00000703-0000-4000-8000-000000000703', 3, 'The basketball hit the rim and bounced out.', 'Quả bóng rổ chạm vành rổ rồi bật ra.'),
('00000704-0000-4000-8000-000000000704', 1, 'They play volleyball on the beach.', 'Họ chơi bóng chuyền trên bãi biển.'),
('00000704-0000-4000-8000-000000000704', 2, 'Our volleyball team won three sets.', 'Đội bóng chuyền của chúng tôi thắng ba set.'),
('00000704-0000-4000-8000-000000000704', 3, 'Volleyball needs good teamwork.', 'Bóng chuyền cần sự phối hợp đồng đội tốt.'),
('00000705-0000-4000-8000-000000000705', 1, 'Badminton is very popular in Vietnam.', 'Cầu lông rất phổ biến ở Việt Nam.'),
('00000705-0000-4000-8000-000000000705', 2, 'We play badminton in the park every morning.', 'Chúng tôi chơi cầu lông trong công viên mỗi sáng.'),
('00000705-0000-4000-8000-000000000705', 3, 'He bought a new badminton racket.', 'Anh ấy mua một cây vợt cầu lông mới.'),
('00000706-0000-4000-8000-000000000706', 1, 'She practices tennis twice a week.', 'Cô ấy tập quần vợt hai lần một tuần.'),
('00000706-0000-4000-8000-000000000706', 2, 'The tennis match lasted three hours.', 'Trận quần vợt kéo dài ba tiếng.'),
('00000706-0000-4000-8000-000000000706', 3, 'Tennis shoes must have good grip.', 'Giày quần vợt phải có độ bám tốt.'),
('00000707-0000-4000-8000-000000000707', 1, 'Table tennis requires quick reactions.', 'Bóng bàn đòi hỏi phản xạ nhanh.'),
